function buildArgumentoLocal(b) {
  const intLink = b.intencionSlug
    ? `<a href="/${b.intencionSlug}">inmobiliaria precio fijo ${b.barrioNombre}</a>`
    : `<a href="/${b.barrioSlug}">vender en ${b.barrioNombre}</a>`;
  const zonasList = b.zonas.join(', ');
  const sitHtml = b.situaciones.map(([t, d]) => `<p><strong>${t}</strong> — ${d}</p>`).join('');
  const errHtml = b.errores.map((e) => `<li>${e}</li>`).join('');
  const local = b.proseLocal || '';

  return `<p>Vender como <strong>particular en ${b.barrioNombre}</strong> empieza con consultas en Idealista o Fotocasa; el freno aparece cuando ninguna oferta llega con hipoteca aprobada. Orientativamente 2026: <strong>${b.precioM2}</strong>; ticket habitual <strong>${b.ticket} €</strong>. Tratar ${b.barrioNombre} como bloque único — sin distinguir ${b.microIntro} — es el error más caro del vendedor autónomo en Barcelona.</p><p>Guía Barcelona: <a href="/vender-como-particular-barcelona">particular en Barcelona</a>. Barrio: ${intLink}.</p><h2>Situaciones que vemos en ${b.barrioNombre}</h2>${sitHtml}<h2>Errores típicos del particular en ${b.cp}</h2><ol>${errHtml}</ol>${local}<h2>Calculadora: ${b.precioDefault.toLocaleString('es-ES')} €</h2><p>6% + IVA ≈ <strong>${b.comision6} €</strong> de comisión tradicional. Precio fijo <strong>3.500 € + IVA</strong>. <a href="#calc">Calculadora</a> — ahorro orientativo superior a <strong>${b.ahorro} €</strong>.</p><h2>Panel del vendedor NuevaHabitat</h2><p>Centraliza visitas, documentos y ofertas. Regístrate en <a href="/registro">la plataforma de particulares</a> o pide <a href="/vender">valoración gratuita</a>. Compradores con estudio hipotecario entran primero.</p><h2>Documentación antes de publicar</h2><ul><li>Certificado energético y cédula si aplica.</li><li>Comunidad e IBI al día; derramas visibles.</li><li>Nota simple sin cargas sorpresa.</li><li>Inquilino: <a href="/blog/vender-piso-alquilado-guia-barcelona">piso alquilado</a>.</li></ul><h2>Micro-zonas</h2><p>${zonasList} — titular concreto en portal, no “Barcelona” genérico.</p><h2>Cuándo pedir valoración</h2><p>Ocho semanas sin oferta financiada; herencia; cadena venta-compra; o coste cerrado antes de mandato. Valoración 24 h desde Les Corts.</p><h2>Próximo paso</h2><p>Calculadora y formulario: micro-zona (${b.microIntro}) y m². Respuesta en 24 h — 3.500 € + IVA solo si cierras.</p>`;
}

